import{_ as e,C as o,o as n,c as s,j as i,E as d,a as l,a3 as r}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (Android)","link":"/mentor/10-sinf-android/"},"n":2,"bob":"I-bob · Android loyihalarini boshqarish va versiya nazorati tizimlari","lessons":[{"g":4,"title":"4-dars: Dependency management va ziddiyatlarni hal qilish","lead":"Dependency management va ziddiyatlarni hal qilish: tranzitiv bog'liqliklar, exclude, resolutionStrategy","link":"/mentor/10-sinf-android/hafta-02/dars-1","slide":"/slaydlar/10-sinf-android/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-android/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: ProGuard va R8 yordamida kodni optimallashtirish (1-qism)","lead":"ProGuard va R8 yordamida kodni optimallashtirish (1-qism): Shrinking, Obfuscation, Optimization","link":"/mentor/10-sinf-android/hafta-02/dars-2","slide":"/slaydlar/10-sinf-android/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-android/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot)","lead":"ProGuard va R8 qoidalari bilan ishlash (2-qism): -keep qoidalari, Reflection, mapping.txt","link":"/mentor/10-sinf-android/hafta-02/dars-3","slide":"/slaydlar/10-sinf-android/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-android/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-android/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-android/hafta-02/index.md","filePath":"mentor/10-sinf-android/hafta-02/index.md"}`),h={name:"mentor/10-sinf-android/hafta-02/index.md"},c={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function y(b,a,q,v,k,p){const t=o("Icon");return n(),s("div",null,[i("div",c,[i("h2",m,[d(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=r('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar to&#39;plami. Har bir vazifa 25–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_4-dars-dependency-management-va-ziddiyatlarni-hal-qilish-tranzitiv-bog-liqliklar" tabindex="-1">4-dars: Dependency management va ziddiyatlarni hal qilish (Tranzitiv bog&#39;liqliklar) <a class="header-anchor" href="#_4-dars-dependency-management-va-ziddiyatlarni-hal-qilish-tranzitiv-bog-liqliklar" aria-label="Permalink to &quot;4-dars: Dependency management va ziddiyatlarni hal qilish (Tranzitiv bog&#39;liqliklar)&quot;">​</a></h2><ol><li>Android Studio loyihangiz terminalida <code>./gradlew app:dependencies --configuration releaseRuntimeClasspath</code> buyrug&#39;ini ishga tushiring.</li><li>Natijada chiqqan bog&#39;liqliklar daraxtidan bitta tranzitiv bog&#39;liqlikni (masalan, <code>androidx.core:core</code> yoki <code>kotlinx-coroutines</code>) aniqlang va u qaysi asosiy kutubxona orqali loyihaga kirib kelganini daftaringizga yozing.</li><li>Loyihada sun&#39;iy ravishda versiya ziddiyati hosil qiling va <code>app/build.gradle</code> faylida <code>exclude group:</code> yoki <code>resolutionStrategy.force</code> yordamida uni yagona barqaror versiyaga moslashtiring.</li></ol><hr><h2 id="_5-dars-proguard-va-r8-yordamida-kodni-optimallashtirish-1-qism" tabindex="-1">5-dars: ProGuard va R8 yordamida kodni optimallashtirish (1-qism) <a class="header-anchor" href="#_5-dars-proguard-va-r8-yordamida-kodni-optimallashtirish-1-qism" aria-label="Permalink to &quot;5-dars: ProGuard va R8 yordamida kodni optimallashtirish (1-qism)&quot;">​</a></h2><ol><li>Android Studio&#39;da <code>app/build.gradle</code> (yoki <code>.kts</code>) faylini oching va <code>buildTypes.release</code> blokiga quyidagi sozlamalarni kiriting: <ul><li><code>isMinifyEnabled = true</code> (yoki Groovy&#39;da <code>minifyEnabled true</code>)</li><li><code>isShrinkResources = true</code> (yoki Groovy&#39;da <code>shrinkResources true</code>)</li></ul></li><li>Terminalda <code>./gradlew assembleRelease</code> buyrug&#39;i orqali Release APK hosil qiling.</li><li>Android Studio menyusidan <strong>Build &gt; Analyze APK...</strong> bo&#39;limini oching va yaratilgan Release APK&#39;ni kiring: <ul><li>Debug va Release APK hajmini solishtiring;</li><li><code>classes.dex</code> ichidagi klass nomlari qanday qisqarganini (masalan, <code>a.b.c</code>) ko&#39;zdan kechiring.</li></ul></li></ol><hr><h2 id="_6-dars-proguard-va-r8-qoidalari-bilan-ishlash-2-qism-amaliyot" tabindex="-1">6-dars: ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot) <a class="header-anchor" href="#_6-dars-proguard-va-r8-qoidalari-bilan-ishlash-2-qism-amaliyot" aria-label="Permalink to &quot;6-dars: ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot)&quot;">​</a></h2><ol><li>Loyihangizda serverdan keladigan ma&#39;lumotlar uchun kamida 2 ta data class yarating: <ul><li><code>UserProfile(val id: Long, val name: String, val role: String)</code></li><li><code>OrderDetails(val orderId: String, val totalSum: Double)</code></li></ul></li><li><code>UserProfile</code> klassini <code>app/proguard-rules.pro</code> faylida <code>-keep class ... { *; }</code> qoidasi orqali himoyalang.</li><li><code>OrderDetails</code> klassiga esa <code>androidx.annotation.Keep</code> kutubxonasidagi <code>@Keep</code> annotatsiyasini qo&#39;llang.</li><li>Loyihani qayta Release build qiling va <code>app/build/outputs/mapping/release/mapping.txt</code> faylini ochib, ushbu klasslar qanday saqlanganini tekshiring.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>4-dars vazifasi (30 ball):</strong> Dependency daraxtini to&#39;g&#39;ri tahlil qilish, tranzitiv ziddiyatlarni aniqlash va <code>exclude</code> qoidasini amalda to&#39;g&#39;ri qo&#39;llay olish.</li><li><strong>5-dars vazifasi (35 ball):</strong> <code>minifyEnabled true</code> va <code>shrinkResources true</code> sozlamalarini xatosiz yoqish, Release build hosil qilish va APK Analyzer orqali hajm o&#39;zgarishini tahlil qilish.</li><li><strong>6-dars vazifasi (35 ball):</strong> Data classlarni <code>proguard-rules.pro</code> fayli hamda <code>@Keep</code> annotatsiyasi orqali himoyalash, <code>mapping.txt</code> faylini topish va tahlil qilish.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar <code>shrinkResources</code> faqat <code>minifyEnabled</code> yoqilganda ishlashini bilishlariga ishonch hosil qiling. Shuningdek, <code>mapping.txt</code> har safar release yig&#39;ilganda yangilanishini va uni arxivlab saqlash professional standart ekanini ta&#39;kidlang.</li></ul>',16))]),i("div",u,[i("h2",g,[d(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=r('<p><strong>Mavzular:</strong></p><ol><li>Dependency management va ziddiyatlarni hal qilish: Tranzitiv bog&#39;liqliklar, dependency tree tahlili, <code>exclude</code> va <code>resolutionStrategy</code></li><li>ProGuard va R8 yordamida kodni optimallashtirish (1-qism): Shrinking, Obfuscation, Optimization, Resource Shrinking, <code>minifyEnabled</code></li><li>ProGuard va R8 qoidalari bilan ishlash (2-qism: Amaliyot): <code>proguard-rules.pro</code>, <code>-keep</code> direktivalari, Gson/Moshi refleksiya muammolari, <code>mapping.txt</code>, <code>@Keep</code></li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Tranzitiv bog&#39;liqliklar va Ziddiyatlar</strong></td><td>Dependency daraxtini terminal orqali chiqarish, to&#39;qnash kelayotgan kutubxona versiyalarini aniqlash va <code>exclude</code> sintaksisini to&#39;g&#39;ri qo&#39;llash</td><td>30 ball</td></tr><tr><td><strong>R8 va Minifikatsiya Asoslari</strong></td><td><code>minifyEnabled</code> va <code>shrinkResources</code> parametrlarini to&#39;g&#39;ri kiritish, APK Analyzer orqali hajm o&#39;zgarishini solishtirish va R8 ishlash tamoyilini tushunish</td><td>35 ball</td></tr><tr><td><strong>ProGuard Qoidalari va Himoya</strong></td><td><code>proguard-rules.pro</code> faylida <code>-keep</code> direktivalarini to&#39;g&#39;ri yozish, <code>@Keep</code> annotatsiyasini qo&#39;llash va <code>mapping.txt</code> orqali deobfuskatsiyani tushunish</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Ziddiyatlar &amp; Exclude (30)</th><th>R8 &amp; Minify (35)</th><th>ProGuard &amp; Rules (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha <code>shrinkResources</code> parametrini <code>minifyEnabled true</code> qilmasdan ishlatishga urinishadi va Gradle xatolik beradi (<code>Resource shrinker requires code shrinker</code>). Shuningdek, model klasslariga <code>-keep</code> qo&#39;yishda paket nomini to&#39;liq yozmaslik tufayli release da crashlar yuzaga kelishi mumkin.</li><li><strong>Tavsiya:</strong> Amaliyot davomida har bir o&#39;quvchiga ataylab DTO modeliga ega ilovani <code>minifyEnabled = true</code> bilan obfuskatsiya qildirib, crash berishini ko&#39;rsatish, so&#39;ngra birgalikda <code>proguard-rules.pro</code> fayliga qoida kiritib tuzatish jarayonini bajarish eng samarali metod hisoblanadi.</li></ul>',11))])])}const x=e(h,[["render",y]]);export{z as __pageData,x as default};
